import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../../core/services/api.service';

@Component({
  selector: 'app-tour-list',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  template: `
    <div class="page-header">
      <div class="container">
        <h1>Tour Du Lịch</h1>
        <p>Chọn tour phù hợp, lên kế hoạch cho chuyến đi hoàn hảo</p>
      </div>
    </div>
    <section class="section">
      <div class="container">
        <div class="filters-bar">
          <div class="filter-search">
            <span class="material-icons">search</span>
            <input type="text" [(ngModel)]="search" (ngModelChange)="loadTours()" placeholder="Tìm kiếm tour..." class="search-input">
          </div>
          <div class="filter-group">
            <select class="form-control" [(ngModel)]="sort" (change)="loadTours()">
              <option value="createdAt">Mới nhất</option>
              <option value="price">Giá: Thấp đến cao</option>
            </select>
          </div>
        </div>
        <div class="loading-spinner" *ngIf="loading"><div class="spinner"></div></div>
        <div class="grid grid-3" *ngIf="!loading">
          <div *ngFor="let t of tours" class="card tour-card fade-in">
            <div class="card-image">
              <img [src]="t.imageUrl || 'https://picsum.photos/seed/' + t.slug + '/400/250'" [alt]="t.name">
              <span class="badge badge-primary card-badge" *ngIf="t.discountPrice">{{ getDiscount(t) }}% OFF</span>
              <span class="badge badge-warning card-badge" *ngIf="t.isFeatured">Hot</span>
            </div>
            <div class="card-body">
              <h3>{{ t.name }}</h3>
              <p class="duration"><span class="material-icons">schedule</span> {{ t.duration }} | {{ t.maxPeople }} người</p>
              <p class="desc">{{ t.shortDescription }}</p>
              <div class="pricing">
                <span class="old" *ngIf="t.discountPrice">{{ t.price | number:'1.0-0' }}đ</span>
                <span class="current">{{ (t.discountPrice || t.price) | number:'1.0-0' }}đ</span>
                <span class="per">/người</span>
              </div>
              <div class="card-actions">
                <a [routerLink]="['/tours', t.slug]" class="btn btn-primary">Chi tiết</a>
                <button class="btn btn-outline" routerLink="/contact">Tư vấn</button>
              </div>
            </div>
          </div>
        </div>
        <div class="empty-state" *ngIf="!loading && tours.length === 0">
          <span class="material-icons">search_off</span>
          <h3>Không tìm thấy tour nào</h3>
        </div>
        <div class="pagination" *ngIf="!loading && pagination.totalPages > 1">
          <button *ngFor="let p of pageNumbers" [class.active]="p === pagination.page" (click)="goToPage(p)">{{ p }}</button>
        </div>
      </div>
    </section>
  `,
  styles: [`
    .tour-card { display: block; text-decoration: none; color: inherit; }
    .card-image { position: relative; height: 200px; overflow: hidden; img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.4s; } }
    .tour-card:hover .card-image img { transform: scale(1.05); }
    .card-badge { position: absolute; top: 12px; }
    h3 { font-size: 1rem; margin-bottom: 0.5rem; }
    .duration { display: flex; align-items: center; gap: 0.25rem; color: var(--gray); font-size: 0.875rem; .material-icons { font-size: 1rem; } }
    .desc { color: var(--gray); font-size: 0.875rem; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; margin-bottom: 0.75rem; }
    .pricing { margin-bottom: 0.75rem; .old { text-decoration: line-through; color: var(--gray-light); font-size: 0.875rem; margin-right: 0.5rem; } .current { font-size: 1.25rem; font-weight: 700; color: var(--danger); } .per { color: var(--gray); font-size: 0.875rem; } }
    .card-actions { display: flex; gap: 0.5rem; .btn { flex: 1; } }
    .filters-bar { display: flex; gap: 1rem; margin-bottom: 2rem; flex-wrap: wrap; }
    .filter-search { flex: 1; min-width: 250px; position: relative; .material-icons { position: absolute; left: 1rem; top: 50%; transform: translateY(-50%); color: var(--gray); } .search-input { padding-left: 2.75rem; } }
    .filter-group { display: flex; gap: 0.75rem; }
  `]
})
export class TourListComponent implements OnInit {
  tours: any[] = [];
  loading = true;
  search = '';
  sort = 'createdAt';
  pagination: any = { page: 1, limit: 12, total: 0, totalPages: 0 };
  pageNumbers: number[] = [];

  constructor(private api: ApiService) {}

  ngOnInit() { this.loadTours(); }

  loadTours() {
    this.loading = true;
    const params: any = { page: this.pagination.page, limit: 12, sort: this.sort };
    if (this.search) params.search = this.search;
    this.api.getTours(params).subscribe({
      next: (res) => {
        this.tours = res.data;
        this.pagination = res.pagination;
        this.pageNumbers = Array.from({length: Math.min(5, res.pagination.totalPages)}, (_, i) => i + 1);
        this.loading = false;
      },
      error: () => { this.loading = false; }
    });
  }

  getDiscount(t: any): number {
    if (!t.discountPrice) return 0;
    return Math.round((1 - t.discountPrice / t.price) * 100);
  }

  goToPage(page: number) {
    this.pagination.page = page;
    this.loadTours();
  }
}
